def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def dfs(current, path):
        row, col = current
        if current == goal:
            return path + [current]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_row, next_col = row + dr, col + dc
            if is_valid(next_row, next_col) and (next_row, next_col) not in path:
                result = dfs((next_row, next_col), path + [current])
                if result:
                    return result
        return []

    return dfs(start, [])
```

