from collections import deque

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Bidirectional BFS: Fronts from start and goal
    start_front = deque([start])
    goal_front = deque([goal])

    # Visited sets for both directions
    visited_start = {start}
    visited_goal = {goal}

    # To keep track of parents for path reconstruction
    parent_start = {}
    parent_goal = {}

    # Queue for BFS
    queue_start = deque([(start, None)])  # (position, parent)
    queue_goal = deque([(goal, None)])   # (position, parent)

    # To track path
    path_found = False
    meeting_point = None

    while start_front and goal_front:
        # Expand start front
        for _ in range(len(start_front)):
            current = start_front.popleft()
            for dx, dy in directions:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited_start:
                    visited_start.add((nx, ny))
                    parent_start[(nx, ny)] = current
                    start_front.append((nx, ny))
                    queue_start.append(( (nx, ny), current ))
                    if (nx, ny) in visited_goal:
                        meeting_point = (nx, ny)
                        path_found = True
                        break
            if path_found:
                break

        # Expand goal front
        for _ in range(len(goal_front)):
            current = goal_front.popleft()
            for dx, dy in directions:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited_goal:
                    visited_goal.add((nx, ny))
                    parent_goal[(nx, ny)] = current
                    goal_front.append((nx, ny))
                    queue_goal.append(( (nx, ny), current ))
                    if (nx, ny) in visited_start:
                        meeting_point = (nx, ny)
                        path_found = True
                        break
            if path_found:
                break

        if path_found:
            break

    if not path_found:
        return []

    # Reconstruct path from start to meeting point
    path = []
    current = meeting_point
    while current is not None:
        path.append(current)
        current = parent_start.get(current)

    # Reconstruct path from goal to meeting point
    current = meeting_point
    while current is not None:
        if current in path:
            break
        path.append(current)
        current = parent_goal.get(current)

    # Reverse path to start to goal
    path.reverse()

    # Verify path is continuous
    for i in range(1, len(path)):
        if path[i][0] != path[i-1][0] and path[i][1] != path[i-1][1]:
            return []

    return path
