def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def dfs(current, path, depth_limit):
        if current == goal:
            return path + [current]

        if depth_limit <= 0:
            return None

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            next_row, next_col = current[0] + dr, current[1] + dc
            if is_valid(next_row, next_col) and (next_row, next_col) not in path:
                result = dfs((next_row, next_col), path + [current], depth_limit - 1)
                if result:
                    return result
        return None

    max_depth = 2 * max(len(grid), len(grid[0]))  # Upper bound on possible depth
    for depth in range(1, max_depth + 1):
        result = dfs(start, [], depth)
        if result:
            return result
    return []
