def solve(grid, start, goal):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current, goal, path, visited, depth_limit):
        if current == goal:
            return path + [current]
        if depth_limit <= 0:
            return None
        visited.add(current)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_r, next_c = current[0] + dr, current[1] + dc
            next_pos = (next_r, next_c)
            if is_valid(next_pos) and next_pos not in visited:
                result = dfs(next_pos, goal, path + [current], visited, depth_limit - 1)
                if result:
                    return result
        return None

    max_depth = 2 * max(rows, cols)  # Upper bound on depth for IDDFS
    for depth in range(1, max_depth + 1):
        visited = set()
        result = dfs(start, goal, [], visited, depth)
        if result:
            return result
    return []
```

