def solve(grid, start, goal):
    from collections import deque

    # Helper function to check if a cell is valid (within bounds and not a wall)
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    # Helper function to perform iterative deepening depth-first search
    def iddfs(start, goal):
        max_depth = 0
        while True:
            # Perform depth-limited search with current max_depth
            visited = set()
            path = []
            if dfs(start, goal, visited, path, 0, max_depth):
                return path
            max_depth += 1

    # Helper function to perform depth-limited DFS
    def dfs(pos, goal, visited, path, depth, max_depth):
        row, col = pos
        if pos == goal:
            path.append(pos)
            return True
        if depth >= max_depth:
            return False
        visited.add((row, col))
        path.append((row, col))
        # Try all four directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and (new_row, new_col) not in visited:
                if dfs((new_row, new_col), goal, visited, path, depth + 1, max_depth):
                    return True
        # Backtrack
        path.pop()
        visited.remove((row, col))
        return False

    # Check if start and goal are valid
    if not is_valid(*start) or not is_valid(*goal):
        return []

    # Run IDDFS
    return iddfs(start, goal)
