def solve(grid, start, goal):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # A* search
    open_set = [(heuristic(start[0], start[1]), 0, start[0], start[1])]
    came_from = {}
    g_score = {start: 0}
    visited = set()

    while open_set:
        _, curr_g, r, c = min(open_set)
        open_set.remove((_, curr_g, r, c))
        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = came_from[(r, c)]
            path.append(start)
            return path[::-1]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                tentative_g = g_score[(r, c)] + 1
                if (nr, nc) not in g_score or tentative_g < g_score[(nr, nc)]:
                    came_from[(nr, nc)] = (r, c)
                    g_score[(nr, nc)] = tentative_g
                    h = heuristic(nr, nc)
                    open_set.append((tentative_g + h, tentative_g, nr, nc))
                    visited.add((nr, nc))

    return []
```

