def solve(n, edges, s, t):
    # If source and target are the same, return 0
    if s == t:
        return 0

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Relax all edges n-1 times
    for i in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # No more updates, early exit

    # If distance to t is still infinity, it's unreachable
    if dist[t] == INF:
        return -1
    else:
        return dist[t]
```

