from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dial's algorithm: bucket-based priority queue
    # Each bucket corresponds to a distance
    # We use a list of queues, where bucket[d] contains nodes at distance d
    # Max possible distance is (n-1)*100 (since each edge has weight 0-100 and n <= 100)
    max_distance = (n - 1) * 100
    buckets = [[] for _ in range(max_distance + 1)]

    # Initialize distance to infinity
    dist = [float('inf')] * n
    dist[s] = 0
    buckets[0].append(s)

    # Dequeue nodes from the front of the bucket
    def dequeue(bucket):
        if bucket:
            return bucket.pop(0)
        return None

    # Process buckets in order
    while buckets:
        for d in range(len(buckets)):
            while buckets[d]:
                u = dequeue(buckets[d])
                for v, w in graph[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        # Add v to the appropriate bucket
                        buckets[dist[v]].append(v)
        # After processing all buckets, check if t was reached
        if dist[t] != float('inf'):
            break

    return dist[t] if dist[t] != float('inf') else -1
