from collections import deque

class Bucket:
    def __init__(self):
        self.nodes = deque()

    def add(self, node):
        self.nodes.append(node)

    def pop(self):
        return self.nodes.popleft()

class BucketPriorityQueue:
    def __init__(self):
        self.buckets = {}

    def __contains__(self, node):
        return node in self.buckets

    def __getitem__(self, node):
        if node not in self.buckets:
            self.buckets[node] = Bucket()
        return self.buckets[node]

    def add(self, node, priority):
        if priority not in self.buckets:
            self.buckets[priority] = Bucket()
        self.buckets[priority].add(node)

    def pop_min(self):
        for priority in sorted(self.buckets.keys()):
            if self.buckets[priority].nodes:
                node = self.buckets[priority].pop()
                del self.buckets[priority] if not self.buckets[priority].nodes else None
                return node, priority
        return None, None

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize distance array and priority queue
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    pq = BucketPriorityQueue()
    pq.add(s, 0)

    # Dial's algorithm
    while True:
        node, priority = pq.pop_min()
        if node is None:
            break
        if dist[node] < priority:
            continue
        for v, w in adj[node]:
            if dist[v] > dist[node] + w:
                dist[v] = dist[node] + w
                pq.add(v, dist[v])

    return dist[t] if dist[t] != INF else -1
